source='''from collections import Counter

def transform(grid):
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    active = [i for i, row in enumerate(grid) if any(v != bg for v in row)]
    if not active:
        return out
    # Split repeated horizontal motifs into vertically separated row groups.
    groups = []
    for i in active:
        if not groups or i != groups[-1][-1] + 1:
            groups.append([i])
        else:
            groups[-1].append(i)
    occupancy = lambda rows: sum(sum(v != bg for v in grid[r]) for r in rows)
    ref_group = max(groups, key=occupancy)
    for group in groups:
        if group is ref_group:
            continue
        # Match rows by within-group position when the motifs have equal height.
        for k, r in enumerate(group):
            if len(group) == len(ref_group):
                rr = ref_group[k]
            else:
                # For ungrouped lines, use the most complete row as a template.
                rr = max((x for g in groups for x in g),
                         key=lambda x: sum(v != bg for v in grid[x]))
            template = grid[rr]
            occupied = [c for c, v in enumerate(grid[r]) if v != bg]
            if not occupied:
                continue
            # Only repair the missing right-hand tail; preserve internal gaps.
            for c in range(occupied[-1] + 1, len(grid[r])):
                if grid[r][c] == bg and template[c] != bg:
                    out[r][c] = 1
    return out
'''
